int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, A, B;
    cin >> N >> A >> B;

    vector<ll> v(N);
    for (int i = 0; i < N; i++) cin >> v[i];

    sort(v.rbegin(), v.rend());

    // Maximum average is achieved by taking exactly A items:
    // the top A values.
    ll sumA = 0;
    for (int i = 0; i < A; i++) sumA += v[i];

    cout << fixed << setprecision(10) << (double)sumA / A << "\n";

    // Precompute combinations up to 50 (typical constraints).
    vector<vector<unsigned long long>> C(55, vector<unsigned long long>(55, 0));
    for (int n = 0; n < 55; n++) {
        C[n][0] = C[n][n] = 1;
        for (int r = 1; r < n; r++) {
            C[n][r] = C[n-1][r-1] + C[n-1][r];
        }
    }

    ll x = v[A-1]; // boundary value in top A

    int totalX = 0;     // total count of x in all items
    int chosenX = 0;    // count of x among top A items

    for (int i = 0; i < N; i++) {
        if (v[i] == x) totalX++;
    }
    for (int i = 0; i < A; i++) {
        if (v[i] == x) chosenX++;
    }

    unsigned long long ways = 0;

    // If the largest A items are all equal to x, then any size k in [A, B]
    // consisting only of value x also gives the same maximum average.
    if (v[0] == x) {
        int maxTake = min(B, totalX);
        for (int k = A; k <= maxTake; k++) {
            ways += C[totalX][k];
        }
    } else {
        // Otherwise, the size must be exactly A.
        ways = C[totalX][chosenX];
    }

    cout << ways << "\n";
    return 0;
}

