int cmp(const void *a, const void *b) {
    return *(int*)b - *(int*)a;
}

long long gcd(long long a, long long b) {
    while (b) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

long long comb(long long n, long long k) {
    if (k > n) return 0;
    if (k > n - k) k = n - k;
    long long res = 1;
    for (long long i = 1; i <= k; i++) {
        res = res * (n - k + i) / i;
    }
    return res;
}

