    scanf("%d %d %d", &N, &A, &B);
    int v[N];
    for (int i = 0; i < N; i++) scanf("%d", &v[i]);
    qsort(v, N, sizeof(int), cmp_desc);

    long long sum = 0;
    for (int i = 0; i < A; i++) sum += v[i];
    int threshold = v[A-1];

    int high = 0;
    while (high < N && v[high] > threshold) high++;
    int equal = 0;
    while (high + equal < N && v[high + equal] == threshold) equal++;
    int need = A - high;

    // C(equal, need)
    // Check if mean == threshold: sum == threshold * A
    long long ways = 0;
    // Compute C(equal, need) * (1 + possible extensions)
    // ... use big numbers? Let's assume they fit in long long

    // C(equal, need)
    long long c = 1;
    for (int i = 0; i < need; i++) {
        c = c * (equal - i) / (i + 1);
    }
    ways = c;

    if (sum == (long long)threshold * A) {
        // Can extend: pick need+1, need+2, ... up to min(equal, need + (B-A)) items from equal
        int extra = equal - need;
        int max_extra = B - A;
        if (extra > max_extra) extra = max_extra;
        for (int add = 1; add <= extra; add++) {
            long long nc = 1;
            int new_need = need + add;
            for (int i = 0; i < new_need; i++) {
                nc = nc * (equal - i) / (i + 1);
            }
            ways += nc;
        }
    }

    printf("%lld/%lld\n%lld\n", sum, (long long)A, ways);
    return 0;
}

