public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int A = sc.nextInt();
        int B = sc.nextInt();
        long[] v = new long[N];
        for (int i = 0; i < N; i++) {
            v[i] = sc.nextLong();
        }

        Arrays.sort(v);
        // reverse to descending order
        for (int i = 0; i < N / 2; i++) {
            long temp = v[i];
            v[i] = v[N - 1 - i];
            v[N - 1 - i] = temp;
        }

        long[] prefixSum = new long[N + 1];
        for (int i = 0; i < N; i++) {
            prefixSum[i + 1] = prefixSum[i] + v[i];
        }

        long bestNum = 0;
        int bestDen = 1;
        long ways = 0;

        for (int k = A; k <= B; k++) {
            long sum = prefixSum[k];
            // Compare sum/k with bestNum/bestDen
            // sum/k > bestNum/bestDen  <=> sum * bestDen > bestNum * k
            if (bestDen == 0 || sum * bestDen > bestNum * k) {
                bestNum = sum;
                bestDen = k;
                ways = countWays(v, k);
            } else if (sum * bestDen == bestNum * k) {
                ways += countWays(v, k);
            }
        }

        double mean = (double) bestNum / bestDen;
        System.out.printf("%.10f%n", mean);
        System.out.println(ways);
    }

    static long countWays(long[] v, int k) {
        // Count how many ways to pick k items from sorted descending v
        // such that sum is maximal = sum of first k items.
        // This happens when we pick all items with value > v[k-1]
        // and some of those equal to v[k-1].
        int N = v.length;
        long target = v[k - 1];
        int totalTarget = 0;
        int inFirstK = 0;
        for (int i = 0; i < N; i++) {
            if (v[i] == target) {
                totalTarget++;
                if (i < k) inFirstK++;
            }
        }
        // We need to choose exactly inFirstK of totalTarget
        return nCr(totalTarget, inFirstK);
    }

    static long nCr(int n, int r) {
        if (r < 0 || r > n) return 0;
        if (r > n - r) r = n - r;
        long res = 1;
        for (int i = 0; i < r; i++) {
            res = res * (n - i) / (i + 1);
        }
        return res;
    }
}

