        // mean = sumA/A (as fraction)
        // count subsets of size k (A<=k<=B) with sum = k*sumA/A
        // i.e., sum*A = k*sumA
        long count = 0;
        // precompute binomial coefficients
        // items: high = count of v[i] > sumA/A... use fraction
        // For each k from A to B, sum needed = k*sumA/A, must be integer
        // group items by value
        // Actually let's count directly
        // items with value > M, = M (as fraction), < M
        // For subset of size k to have sum = k*sumA/A:
        // only feasible if all items are equal to M (if M is integer) or specific combos
        // Let's just brute force count for small N
        // N can be large? Problem doesn't specify... assume N<=50 or so
        // Use big combinatorics
        // Find how many items equal top value, etc.
        // Simplified: all items in optimal must be from top items only
        // Actually mean of top A >= mean of any A items, so optimal is top A
        // For larger subsets, mean can only equal if extra items = M
        // Let me just implement carefully
        long g = gcd(sumA, A);
        long numM = sumA/g, denM = A/g; // mean = numM/denM
        // count items with value*denM == numM (value == M)
        // count items with value > M
        int cntHigh = 0, cntEqual = 0;
        for (long x : v) { if (x*denM > numM) cntHigh++; else if (x*denM == numM) cntEqual++; }
        for (int k = A; k <= B; k++) {
            int need = k - cntHigh; // need this many from equal
            if (need >= 0 && need <= cntEqual) count += comb(cntEqual, need);
        }
        System.out.println((double)sumA/A);
        System.out.println(count);
    }
    static long gcd(long a, long b) { return b==0?a:gcd(b,a%b); }
    static long comb(int n, int k) {
        if (k<0||k>n) return 0;
        BigInteger r = BigInteger.ONE;
        for (int i=0;i<k;i++) r=r.multiply(BigInteger.valueOf(n-i)).divide(BigInteger.valueOf(i+1));
        return r.longValue();
    }
