    static long[][] comb = new long[51][51];

    static void buildComb() {
        for (int n = 0; n <= 50; n++) {
            comb[n][0] = comb[n][n] = 1;
            for (int r = 1; r < n; r++) {
                comb[n][r] = comb[n - 1][r - 1] + comb[n - 1][r];
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int A = fs.nextInt();
        int B = fs.nextInt();

        long[] v = new long[N];
        for (int i = 0; i < N; i++) v[i] = fs.nextLong();

        Arrays.sort(v);
        // descending
        for (int i = 0; i < N / 2; i++) {
            long tmp = v[i];
            v[i] = v[N - 1 - i];
            v[N - 1 - i] = tmp;
        }

        buildComb();

        long sumA = 0;
        for (int i = 0; i < A; i++) sumA += v[i];
        double maxMean = (double) sumA / A;

        long x = v[A - 1]; // boundary value

        int totalX = 0;
        int usedXInA = 0;
        for (int i = 0; i < N; i++) {
            if (v[i] == x) totalX++;
        }
        for (int i = 0; i < A; i++) {
            if (v[i] == x) usedXInA++;
        }

        long ways = 0;

        // If the top A values are all equal to the maximum value,
        // then choosing more of the same value keeps the same mean.
        if (v[0] == x) {
            int maxK = Math.min(B, totalX);
            for (int k = A; k <= maxK; k++) {
                ways += comb[totalX][k];
            }
        } else {
            // Only choosing exactly A items can achieve the maximum mean.
            ways = comb[totalX][usedXInA];
        }

        System.out.printf("%.6f%n", maxMean);
        System.out.println(ways);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
